-- Maati Living — PRODUCTION database setup (generated by scripts/build-production-sql.mjs; don't edit by hand).
-- Run ONCE on a NEW, EMPTY Supabase project: SQL Editor → New query → paste this whole file → Run.
-- Contains migrations 0001–0011 in order and marks the database as production
-- (which also blocks the demo seed). No sample products or demo data. For an existing database, run only the
-- migrations it doesn't have yet, one file at a time, from supabase/migrations/.

-- ===========================================================================
-- 0001_auth_and_catalogue.sql
-- ===========================================================================

-- Maati Living — Phase 1 + 2 schema: profiles/roles and the product catalogue.
-- Run once in Supabase → SQL Editor (or `supabase db push`).

-- ---------------------------------------------------------------------------
-- Profiles + roles
-- ---------------------------------------------------------------------------

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  full_name text,
  role text not null default 'customer' check (role in ('admin', 'customer')),
  created_at timestamptz not null default now()
);

-- Every new auth user gets a profile with role 'customer'. Admins are promoted by hand (see docs/SETUP.md).
create function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, new.raw_user_meta_data ->> 'full_name');
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- security definer so policies can call it without recursing through profiles RLS.
create function public.is_admin()
returns boolean
language sql
stable
security definer set search_path = ''
as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin');
$$;

alter table public.profiles enable row level security;

-- No insert/update/delete policies: roles can only be changed from the SQL editor.
create policy "Users read own profile" on public.profiles
  for select using (id = auth.uid());
create policy "Admins read all profiles" on public.profiles
  for select using (public.is_admin());

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------

create table public.categories (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  description text,
  parent_id uuid references public.categories (id) on delete set null,
  image_public_id text,
  image_alt text,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  category_id uuid references public.categories (id) on delete restrict,
  price_paise int not null check (price_paise >= 0),
  stock int not null default 0 check (stock >= 0),
  short_description text,
  sourcing_note text,
  materials text[] not null default '{}',
  artisan text,
  region text,
  care text,
  is_available boolean not null default true,
  is_featured boolean not null default false,
  sku text unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  public_id text not null,
  alt text not null default '',
  sort_order int not null default 0
);

create index products_category_id_idx on public.products (category_id);
create index product_images_product_id_idx on public.product_images (product_id, sort_order);

create function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger products_touch_updated_at
  before update on public.products
  for each row execute function public.touch_updated_at();

alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.product_images enable row level security;

-- Public (anon + signed-in) can read the catalogue; hidden products only by admins.
create policy "Anyone reads categories" on public.categories
  for select using (true);
create policy "Anyone reads available products" on public.products
  for select using (is_available or public.is_admin());
create policy "Anyone reads images of available products" on public.product_images
  for select using (
    exists (select 1 from public.products p where p.id = product_id and (p.is_available or public.is_admin()))
  );

-- Only admins write.
create policy "Admins manage categories" on public.categories
  for all using (public.is_admin()) with check (public.is_admin());
create policy "Admins manage products" on public.products
  for all using (public.is_admin()) with check (public.is_admin());
create policy "Admins manage product images" on public.product_images
  for all using (public.is_admin()) with check (public.is_admin());

-- ===========================================================================
-- 0002_orders.sql
-- ===========================================================================

-- Maati Living — Phase 3: orders and order items.
-- Run in Supabase → SQL Editor after 0001.
--
-- Guest checkout writes orders with the server-only secret key (bypasses RLS), so there are
-- deliberately no anon/customer policies here. Customers see their order through a
-- server-rendered page keyed by order number + access token.

create sequence public.order_number_seq start 1001;

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique default ('ML' || nextval('public.order_number_seq')),
  access_token uuid not null default gen_random_uuid(),
  user_id uuid references auth.users (id) on delete set null, -- linked in Phase 4 (accounts)
  status text not null default 'pending'
    check (status in ('pending', 'paid', 'failed', 'cancelled', 'shipped', 'delivered')),
  customer_name text not null,
  email text not null,
  phone text not null,
  address_line1 text not null,
  address_line2 text,
  city text not null,
  state text not null,
  pincode text not null,
  notes text,
  subtotal_paise int not null check (subtotal_paise >= 0),
  shipping_paise int not null check (shipping_paise >= 0),
  total_paise int not null check (total_paise >= 0),
  razorpay_order_id text unique,
  razorpay_payment_id text,
  paid_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Snapshot of each line at purchase time; survives product edits and deletes.
create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  product_name text not null,
  product_slug text,
  image_public_id text,
  unit_price_paise int not null check (unit_price_paise >= 0),
  quantity int not null check (quantity > 0)
);

create index orders_created_at_idx on public.orders (created_at desc);
create index orders_status_idx on public.orders (status);
create index order_items_order_id_idx on public.order_items (order_id);

create trigger orders_touch_updated_at
  before update on public.orders
  for each row execute function public.touch_updated_at();

alter table public.orders enable row level security;
alter table public.order_items enable row level security;

create policy "Admins read orders" on public.orders
  for select using (public.is_admin());
create policy "Admins update orders" on public.orders
  for update using (public.is_admin()) with check (public.is_admin());
create policy "Admins read order items" on public.order_items
  for select using (public.is_admin());

-- Marks an order paid and takes its items out of stock, exactly once.
-- Called only by the server after verifying Razorpay's signature (checkout or webhook).
create function public.mark_order_paid(p_razorpay_order_id text, p_payment_id text)
returns table (order_id uuid, newly_paid boolean)
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  update public.orders
     set status = 'paid', razorpay_payment_id = p_payment_id, paid_at = now()
   where razorpay_order_id = p_razorpay_order_id and status in ('pending', 'failed')
   returning id into v_id;

  if v_id is null then
    -- Already paid (e.g. webhook and browser both confirmed) or unknown order.
    return query select o.id, false from public.orders o where o.razorpay_order_id = p_razorpay_order_id;
    return;
  end if;

  update public.products p
     set stock = greatest(p.stock - oi.quantity, 0)
    from public.order_items oi
   where oi.order_id = v_id and oi.product_id = p.id;

  return query select v_id, true;
end;
$$;

revoke execute on function public.mark_order_paid(text, text) from public, anon, authenticated;
grant execute on function public.mark_order_paid(text, text) to service_role;

-- ===========================================================================
-- 0003_customer_accounts.sql
-- ===========================================================================

-- Maati Living — Phase 4: customer accounts.
-- Run in Supabase → SQL Editor after 0002.

-- ---------------------------------------------------------------------------
-- Profile: customers may edit their own name and phone — never their role.
-- ---------------------------------------------------------------------------

alter table public.profiles add column phone text;

-- Column-level privilege is what protects `role`: authenticated users can only UPDATE these two columns.
revoke update on public.profiles from anon, authenticated;
grant update (full_name, phone) on public.profiles to authenticated;

create policy "Users update own profile" on public.profiles
  for update using (id = auth.uid()) with check (id = auth.uid());

-- ---------------------------------------------------------------------------
-- Saved addresses
-- ---------------------------------------------------------------------------

create table public.addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null,
  phone text not null,
  line1 text not null,
  line2 text,
  city text not null,
  state text not null,
  pincode text not null,
  is_default boolean not null default false,
  created_at timestamptz not null default now()
);

create index addresses_user_id_idx on public.addresses (user_id);
-- At most one default address per customer.
create unique index addresses_one_default_idx on public.addresses (user_id) where is_default;

alter table public.addresses enable row level security;

create policy "Users manage own addresses" on public.addresses
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Orders: customers read their own (linked by user_id)
-- ---------------------------------------------------------------------------

create policy "Customers read own orders" on public.orders
  for select using (user_id = auth.uid());
create policy "Customers read own order items" on public.order_items
  for select using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = auth.uid()));

-- Links earlier guest orders to an account by (verified) email. Called by the server with the
-- secret key after confirming the user's email is verified.
create function public.claim_guest_orders(p_user_id uuid, p_email text)
returns int
language sql
security definer set search_path = ''
as $$
  with claimed as (
    update public.orders set user_id = p_user_id
     where user_id is null and lower(email) = lower(p_email)
     returning 1
  )
  select count(*)::int from claimed;
$$;

revoke execute on function public.claim_guest_orders(uuid, text) from public, anon, authenticated;
grant execute on function public.claim_guest_orders(uuid, text) to service_role;

-- ===========================================================================
-- 0004_admin_operations.sql
-- ===========================================================================

-- Maati Living — Phase 5: admin operations (shipping/tracking, refunds, restock, store settings).
-- Run in Supabase → SQL Editor after 0003.

-- ---------------------------------------------------------------------------
-- Orders: tracking, refunds, restock flag, 'refunded' status
-- ---------------------------------------------------------------------------

alter table public.orders drop constraint orders_status_check;
alter table public.orders add constraint orders_status_check
  check (status in ('pending', 'paid', 'failed', 'cancelled', 'shipped', 'delivered', 'refunded'));

alter table public.orders
  add column tracking_courier text,
  add column tracking_number text,
  add column shipped_at timestamptz,
  add column refund_id text,
  add column refund_amount_paise int check (refund_amount_paise >= 0),
  add column refunded_at timestamptz,
  add column restocked boolean not null default false;

-- Puts an order's items back into stock, at most once per order. Admin-only.
create function public.admin_restock_order(p_order_id uuid)
returns boolean
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    return false; -- non-admins: no-op
  end if;

  update public.orders set restocked = true
   where id = p_order_id and not restocked and status in ('cancelled', 'refunded')
   returning id into v_id;
  if v_id is null then
    return false;
  end if;

  update public.products p
     set stock = p.stock + oi.quantity
    from public.order_items oi
   where oi.order_id = v_id and oi.product_id = p.id;
  return true;
end;
$$;

revoke execute on function public.admin_restock_order(uuid) from public, anon;
grant execute on function public.admin_restock_order(uuid) to authenticated; -- is_admin() check inside

-- ---------------------------------------------------------------------------
-- Store settings (key → JSON), e.g. delivery charges
-- ---------------------------------------------------------------------------

create table public.settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

create trigger settings_touch_updated_at
  before update on public.settings
  for each row execute function public.touch_updated_at();

alter table public.settings enable row level security;

-- Delivery charges are shown in the cart, so everyone may read settings. Only admins change them.
create policy "Anyone reads settings" on public.settings
  for select using (true);
create policy "Admins manage settings" on public.settings
  for all using (public.is_admin()) with check (public.is_admin());

insert into public.settings (key, value) values
  ('shipping', '{"defaultPaise": 9900, "freeOverPaise": 99900, "byStatePaise": {}}');

-- ===========================================================================
-- 0005_manual_upi.sql
-- ===========================================================================

-- Maati Living — direct UPI payments (PhonePe / Google Pay / Paytm / BHIM) checked by hand.
-- Used until Razorpay is live. Run in Supabase → SQL Editor after 0004.
--
-- Flow: customer places an order (status 'pending', payment_method 'upi_manual'), pays the shown UPI ID,
-- submits the UPI transaction id (UTR). The admin checks the money arrived and confirms it, which marks the
-- order paid and takes the items out of stock, exactly once.

alter table public.orders
  add column payment_method text not null default 'razorpay' check (payment_method in ('razorpay', 'upi_manual')),
  add column payment_reference text,          -- UPI transaction id (UTR) entered by the customer
  add column payment_submitted_at timestamptz;

create index orders_payment_method_status_idx on public.orders (payment_method, status);

-- Admin-only. Returns true when this call marked the order paid (false for non-admins, wrong
-- method/status, or if it was already confirmed) so callers know whether to send emails.
create function public.admin_confirm_manual_payment(p_order_id uuid)
returns boolean
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    return false;
  end if;

  update public.orders
     set status = 'paid', paid_at = now()
   where id = p_order_id and payment_method = 'upi_manual' and status = 'pending'
   returning id into v_id;
  if v_id is null then
    return false;
  end if;

  update public.products p
     set stock = greatest(p.stock - oi.quantity, 0)
    from public.order_items oi
   where oi.order_id = v_id and oi.product_id = p.id;
  return true;
end;
$$;

revoke execute on function public.admin_confirm_manual_payment(uuid) from public, anon;
grant execute on function public.admin_confirm_manual_payment(uuid) to authenticated; -- is_admin() check inside

-- Restock only orders that were actually paid: an unpaid order that's cancelled never took stock out.
create or replace function public.admin_restock_order(p_order_id uuid)
returns boolean
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    return false; -- non-admins: no-op
  end if;

  update public.orders set restocked = true
   where id = p_order_id and not restocked and status in ('cancelled', 'refunded') and paid_at is not null
   returning id into v_id;
  if v_id is null then
    return false;
  end if;

  update public.products p
     set stock = p.stock + oi.quantity
    from public.order_items oi
   where oi.order_id = v_id and oi.product_id = p.id;
  return true;
end;
$$;

-- ===========================================================================
-- 0006_carts.sql
-- ===========================================================================

-- Maati Living — saved carts for signed-in customers (synced across devices).
-- Run in Supabase → SQL Editor after 0005. Guests keep their cart in the browser.
--
-- items is a convenience copy ([{ productId, slug, name, price, imagePublicId, maxQuantity, quantity }]).
-- It is never trusted for money: checkout re-prices every line from the products table.

create table public.carts (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  items jsonb not null default '[]'::jsonb check (jsonb_typeof(items) = 'array'),
  updated_at timestamptz not null default now()
);

create trigger carts_touch_updated_at
  before update on public.carts
  for each row execute function public.touch_updated_at();

alter table public.carts enable row level security;

create policy "Users manage own cart" on public.carts
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ===========================================================================
-- 0007_books_foundation.sql
-- ===========================================================================

-- Maati Living — Books, Phase 1: stock ledger, cost price, vendors, audit log.
-- Run in Supabase → SQL Editor after 0006. TAKE A BACKUP FIRST and run on the dev/test project first.
--
-- Principles
--   * stock_movements is the single source of truth for every stock change. products.stock can only
--     change inside the approved functions below (a guard trigger blocks any other UPDATE of stock).
--   * Every money/stock function is one transaction: it either fully succeeds or RAISEs and rolls back.
--   * Admin-only everything (is_admin()), checked inside each function as well as by RLS.
--   * audit_log records who/what/before/after for every change to Books tables.

-- ---------------------------------------------------------------------------
-- 1. New columns (nothing dropped or rewritten)
-- ---------------------------------------------------------------------------

alter table public.products
  add column cost_price_paise int check (cost_price_paise >= 0),          -- weighted average cost; null = not set
  add column low_stock_threshold int check (low_stock_threshold >= 0);    -- null = shop default (5)

alter table public.order_items
  add column unit_cost_paise int check (unit_cost_paise >= 0);            -- cost snapshot when the order is paid

-- ---------------------------------------------------------------------------
-- 2. Audit log (written by trigger; readable by admins only)
-- ---------------------------------------------------------------------------

create table public.audit_log (
  id bigint generated always as identity primary key,
  actor_id uuid,                 -- auth.uid() of the admin; null only for system writes (payment gateway/webhook)
  actor_kind text not null,      -- 'user' | 'system'
  entity text not null,          -- table name
  entity_id text,
  action text not null,          -- insert | update | delete
  before jsonb,
  after jsonb,
  created_at timestamptz not null default now()
);

create index audit_log_entity_idx on public.audit_log (entity, entity_id, created_at desc);

alter table public.audit_log enable row level security;
create policy "Admins read audit log" on public.audit_log for select using (public.is_admin());
revoke insert, update, delete on public.audit_log from anon, authenticated;

create function public.audit_row()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
begin
  insert into public.audit_log (actor_id, actor_kind, entity, entity_id, action, before, after)
  values (
    v_actor,
    case when v_actor is null then 'system' else 'user' end,
    tg_table_name,
    v_row ->> 'id',
    lower(tg_op),
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end
  );
  return null;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Stock ledger
-- ---------------------------------------------------------------------------

create table public.stock_movements (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete restrict, -- history keeps the product
  qty_change int not null check (qty_change <> 0),
  reason text not null check (reason in ('opening_stock', 'purchase_receipt', 'order_paid', 'order_cancel_restock', 'manual_adjustment')),
  adjustment_reason text check (adjustment_reason in ('damaged', 'lost', 'sample', 'recount', 'other')),
  ref_type text check (ref_type in ('order', 'purchase', 'adjustment')),
  ref_id uuid,
  unit_cost_paise int check (unit_cost_paise >= 0),
  stock_after int not null check (stock_after >= 0),
  note text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  check (reason <> 'manual_adjustment' or adjustment_reason is not null)
);

create index stock_movements_product_idx on public.stock_movements (product_id, created_at desc);
create index stock_movements_ref_idx on public.stock_movements (ref_type, ref_id);

alter table public.stock_movements enable row level security;
create policy "Admins read stock movements" on public.stock_movements for select using (public.is_admin());
-- Immutable from the API: only the functions below write it.
revoke insert, update, delete on public.stock_movements from anon, authenticated;

create trigger stock_movements_audit after insert on public.stock_movements
  for each row execute function public.audit_row();

-- Guard: products.stock may only change inside an approved function (which sets maati.stock_write).
create function public.guard_stock_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.stock is distinct from old.stock and coalesce(current_setting('maati.stock_write', true), '') <> 'on' then
    raise exception 'Stock can only change through a stock movement (use Adjust stock).' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create trigger products_guard_stock before update on public.products
  for each row execute function public.guard_stock_update();

-- New product created with initial stock → opening_stock movement, in the same transaction.
create function public.products_opening_stock()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  if new.stock > 0 then
    insert into public.stock_movements (product_id, qty_change, reason, unit_cost_paise, stock_after, note)
    values (new.id, new.stock, 'opening_stock', new.cost_price_paise, new.stock, 'Initial stock when the product was created');
  end if;
  return null;
end;
$$;

create trigger products_opening_stock after insert on public.products
  for each row execute function public.products_opening_stock();

-- Products: audit cost / stock / price / visibility changes.
create trigger products_audit after update of stock, cost_price_paise, price_paise, low_stock_threshold, is_available on public.products
  for each row execute function public.audit_row();

-- Internal: change one product's stock and record the movement. Raises (rolls back the caller) if it would go
-- negative. Not callable from the API (no grant); used only by the security-definer functions below.
create function public._stock_move(
  p_product_id uuid, p_qty int, p_reason text, p_ref_type text, p_ref_id uuid,
  p_unit_cost int default null, p_note text default null, p_adjustment_reason text default null
)
returns int
language plpgsql
security definer set search_path = ''
as $$
declare
  v_stock int;
begin
  if p_qty = 0 then
    return (select stock from public.products where id = p_product_id);
  end if;
  select stock into v_stock from public.products where id = p_product_id for update;
  if v_stock is null then
    raise exception 'Product not found' using errcode = 'P0002';
  end if;
  if v_stock + p_qty < 0 then
    raise exception 'Not enough stock: % in stock, change of % would go below zero', v_stock, p_qty using errcode = 'P0001';
  end if;
  perform set_config('maati.stock_write', 'on', true);
  update public.products set stock = v_stock + p_qty where id = p_product_id;
  perform set_config('maati.stock_write', 'off', true);
  insert into public.stock_movements (product_id, qty_change, reason, adjustment_reason, ref_type, ref_id, unit_cost_paise, stock_after, note)
  values (p_product_id, p_qty, p_reason, p_adjustment_reason, p_ref_type, p_ref_id, p_unit_cost, v_stock + p_qty, p_note);
  return v_stock + p_qty;
end;
$$;

revoke execute on function public._stock_move(uuid, int, text, text, uuid, int, text, text) from public, anon, authenticated;

-- Backfill: one opening_stock movement per product that has stock today (cost unknown → null).
insert into public.stock_movements (product_id, qty_change, reason, unit_cost_paise, stock_after, note, created_by)
select id, stock, 'opening_stock', cost_price_paise, stock, 'Opening stock when the stock ledger started', null
from public.products
where stock > 0;

-- ---------------------------------------------------------------------------
-- 4. Existing order flows, now recording movements + cost snapshot (same stock behaviour)
-- ---------------------------------------------------------------------------

-- Internal: take an order's items out of stock exactly like before (never below zero: an oversold
-- line takes what's left), record movements, and snapshot each line's unit cost.
create function public._order_stock_out(p_order_id uuid)
returns void
language plpgsql
security definer set search_path = ''
as $$
declare
  r record;
  v_stock int;
  v_take int;
begin
  for r in
    select oi.id as item_id, oi.product_id, oi.quantity, p.cost_price_paise
      from public.order_items oi
      join public.products p on p.id = oi.product_id
     where oi.order_id = p_order_id
     order by oi.id
  loop
    update public.order_items set unit_cost_paise = r.cost_price_paise where id = r.item_id;
    select stock into v_stock from public.products where id = r.product_id for update;
    v_take := least(r.quantity, v_stock);
    if v_take > 0 then
      perform public._stock_move(r.product_id, -v_take, 'order_paid', 'order', p_order_id, r.cost_price_paise,
        case when v_take < r.quantity then format('Oversold: ordered %s, only %s in stock', r.quantity, v_take) end);
    end if;
  end loop;
end;
$$;

revoke execute on function public._order_stock_out(uuid) from public, anon, authenticated;

create or replace function public.mark_order_paid(p_razorpay_order_id text, p_payment_id text)
returns table (order_id uuid, newly_paid boolean)
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  update public.orders
     set status = 'paid', razorpay_payment_id = p_payment_id, paid_at = now()
   where razorpay_order_id = p_razorpay_order_id and status in ('pending', 'failed')
   returning id into v_id;

  if v_id is null then
    return query select o.id, false from public.orders o where o.razorpay_order_id = p_razorpay_order_id;
    return;
  end if;

  perform public._order_stock_out(v_id);
  return query select v_id, true;
end;
$$;

revoke execute on function public.mark_order_paid(text, text) from public, anon, authenticated;
grant execute on function public.mark_order_paid(text, text) to service_role;

create or replace function public.admin_confirm_manual_payment(p_order_id uuid)
returns boolean
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  update public.orders
     set status = 'paid', paid_at = now()
   where id = p_order_id and payment_method = 'upi_manual' and status = 'pending'
   returning id into v_id;
  if v_id is null then
    return false; -- already confirmed / not an unpaid UPI order: nothing was written
  end if;

  perform public._order_stock_out(v_id);
  return true;
end;
$$;

create or replace function public.admin_restock_order(p_order_id uuid)
returns boolean
language plpgsql
security definer set search_path = ''
as $$
declare
  v_id uuid;
  r record;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  update public.orders set restocked = true
   where id = p_order_id and not restocked and status in ('cancelled', 'refunded') and paid_at is not null
   returning id into v_id;
  if v_id is null then
    return false; -- already restocked / not eligible: nothing was written
  end if;

  for r in select product_id, sum(quantity)::int as qty from public.order_items where order_id = v_id and product_id is not null group by product_id loop
    perform public._stock_move(r.product_id, r.qty, 'order_cancel_restock', 'order', v_id, null, null);
  end loop;
  return true;
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Manual stock adjustment and cost price (admin)
-- ---------------------------------------------------------------------------

create function public.books_adjust_stock(p_product_id uuid, p_qty_change int, p_reason text, p_note text default null)
returns int
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if p_qty_change is null or p_qty_change = 0 then
    raise exception 'Enter how many to add or remove (not 0).' using errcode = 'P0001';
  end if;
  if p_reason not in ('damaged', 'lost', 'sample', 'recount', 'other') then
    raise exception 'Choose a reason for the adjustment.' using errcode = 'P0001';
  end if;
  if p_reason = 'other' and coalesce(btrim(p_note), '') = '' then
    raise exception 'Add a note explaining the adjustment.' using errcode = 'P0001';
  end if;
  return public._stock_move(p_product_id, p_qty_change, 'manual_adjustment', 'adjustment', null,
    (select cost_price_paise from public.products where id = p_product_id), nullif(btrim(p_note), ''), p_reason);
end;
$$;

revoke execute on function public.books_adjust_stock(uuid, int, text, text) from public, anon;
grant execute on function public.books_adjust_stock(uuid, int, text, text) to authenticated; -- is_admin() inside

create function public.books_set_cost_price(p_product_id uuid, p_cost_paise int)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if p_cost_paise is not null and p_cost_paise < 0 then
    raise exception 'Cost price can''t be negative.' using errcode = 'P0001';
  end if;
  update public.products set cost_price_paise = p_cost_paise where id = p_product_id;
  if not found then
    raise exception 'Product not found' using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function public.books_set_cost_price(uuid, int) from public, anon;
grant execute on function public.books_set_cost_price(uuid, int) to authenticated; -- is_admin() inside

-- ---------------------------------------------------------------------------
-- 6. Vendors
-- ---------------------------------------------------------------------------

create table public.vendors (
  id uuid primary key default gen_random_uuid(),
  name text not null check (btrim(name) <> ''),
  contact_person text,
  phone text check (phone ~ '^[6-9][0-9]{9}$'),
  whatsapp text check (whatsapp ~ '^[6-9][0-9]{9}$'),
  email text,
  city text,
  state text,
  address text,
  gstin text check (gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  pan text check (pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$'),
  upi_id text,
  bank_account_name text,
  bank_account_number text check (bank_account_number ~ '^[0-9]{9,18}$'),
  bank_ifsc text check (bank_ifsc ~ '^[A-Z]{4}0[A-Z0-9]{6}$'),
  supplies text,                       -- free tags, e.g. "diyas, coconut shell"
  notes text,
  rating int check (rating between 1 and 5),
  payment_terms_days int not null default 0 check (payment_terms_days between 0 and 365),
  opening_balance_paise int not null default 0,   -- what we owed them on day one (negative = advance)
  status text not null default 'active' check (status in ('active', 'archived')),
  archived_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index vendors_status_idx on public.vendors (status, name);

create trigger vendors_touch_updated_at before update on public.vendors
  for each row execute function public.touch_updated_at();
create trigger vendors_audit after insert or update or delete on public.vendors
  for each row execute function public.audit_row();

alter table public.vendors enable row level security;
create policy "Admins read vendors" on public.vendors for select using (public.is_admin());
create policy "Admins add vendors" on public.vendors for insert with check (public.is_admin());
create policy "Admins edit vendors" on public.vendors for update using (public.is_admin()) with check (public.is_admin());
-- No delete policy: vendors are archived, never deleted.

create table public.vendor_products (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  product_id uuid not null references public.products (id) on delete restrict,
  vendor_sku text,
  last_cost_paise int check (last_cost_paise >= 0),
  is_preferred boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (vendor_id, product_id)
);

create unique index vendor_products_one_preferred_idx on public.vendor_products (product_id) where is_preferred;

create trigger vendor_products_touch_updated_at before update on public.vendor_products
  for each row execute function public.touch_updated_at();
create trigger vendor_products_audit after insert or update or delete on public.vendor_products
  for each row execute function public.audit_row();

alter table public.vendor_products enable row level security;
create policy "Admins manage vendor products" on public.vendor_products
  for all using (public.is_admin()) with check (public.is_admin());

-- Make a vendor the preferred supplier of a product (clears the previous one) in one step.
create function public.books_set_preferred_vendor(p_vendor_id uuid, p_product_id uuid)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  update public.vendor_products set is_preferred = false where product_id = p_product_id and is_preferred and vendor_id <> p_vendor_id;
  update public.vendor_products set is_preferred = true where product_id = p_product_id and vendor_id = p_vendor_id;
  if not found then
    raise exception 'This vendor doesn''t supply that product yet.' using errcode = 'P0002';
  end if;
end;
$$;

revoke execute on function public.books_set_preferred_vendor(uuid, uuid) from public, anon;
grant execute on function public.books_set_preferred_vendor(uuid, uuid) to authenticated; -- is_admin() inside

-- ===========================================================================
-- 0008_books_purchases.sql
-- ===========================================================================

-- Maati Living — Books, Phase 2: purchases (purchase order + bill), receiving stock, landed + weighted average cost.
-- Run in Supabase → SQL Editor after 0007. TAKE A BACKUP FIRST and run on the dev/test project first.
-- Nothing existing is dropped or rewritten; books_set_cost_price is replaced with a stricter version (cost > 0).
--
-- Rules
--   * Purchases and their lines are written only through the functions below (one transaction each, RAISE on
--     any problem so nothing half-saves). The API can read them (admins) but not insert/update/delete directly.
--   * Once anything has been received, a purchase can't be cancelled and its lines / amounts can't change;
--     corrections go through Adjust stock plus a note on the purchase. Bill details, notes and files stay editable.
--   * Receiving: stock up (purchase_receipt movement), landed unit cost = unit cost with the purchase's
--     shipping minus discount spread by line value, product cost = weighted average (first receipt sets it
--     when the cost isn't known yet), vendor's last cost updated.
--   * Receiving more than ordered is allowed only when the admin confirmed it (p_allow_over); the bill
--     then counts the pieces actually received for that line.

-- ---------------------------------------------------------------------------
-- 1. Cost price must be more than ₹0 (blank/null still clears it)
-- ---------------------------------------------------------------------------

create or replace function public.books_set_cost_price(p_product_id uuid, p_cost_paise int)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if p_cost_paise is not null and p_cost_paise <= 0 then
    raise exception 'Cost price must be more than ₹0. Leave it blank if you don''t know it yet.' using errcode = 'P0001';
  end if;
  update public.products set cost_price_paise = p_cost_paise where id = p_product_id;
  if not found then
    raise exception 'Product not found' using errcode = 'P0002';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. Tables
-- ---------------------------------------------------------------------------

create sequence public.purchase_number_seq start 1001;
revoke all on sequence public.purchase_number_seq from public, anon, authenticated;

create table public.purchases (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,                       -- PO-1001, PO-1002, …
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  status text not null default 'draft' check (status in ('draft', 'ordered', 'partially_received', 'received', 'cancelled')),
  order_date date not null default ((now() at time zone 'Asia/Kolkata')::date),
  expected_date date,
  bill_number text check (char_length(bill_number) <= 60),
  bill_date date,
  bill_attachments jsonb not null default '[]'::jsonb check (jsonb_typeof(bill_attachments) = 'array'),
  subtotal_paise int not null default 0 check (subtotal_paise >= 0),
  discount_paise int not null default 0 check (discount_paise >= 0),
  shipping_paise int not null default 0 check (shipping_paise >= 0),   -- freight we paid on this purchase
  tax_paise int not null default 0 check (tax_paise >= 0),             -- optional, for future GST
  total_paise int not null default 0,
  due_date date,                                                       -- bill date + vendor's payment terms (editable)
  notes text check (char_length(notes) <= 2000),
  ordered_at timestamptz,
  received_at timestamptz,
  cancelled_at timestamptz,
  cancelled_reason text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (discount_paise <= subtotal_paise),
  check (total_paise = subtotal_paise - discount_paise + shipping_paise + tax_paise),
  check (status <> 'cancelled' or cancelled_reason is not null)
);

create index purchases_status_idx on public.purchases (status, order_date desc);
create index purchases_vendor_idx on public.purchases (vendor_id, order_date desc);

create table public.purchase_items (
  id uuid primary key default gen_random_uuid(),
  purchase_id uuid not null references public.purchases (id) on delete restrict,
  product_id uuid not null references public.products (id) on delete restrict,
  qty_ordered int not null check (qty_ordered > 0),
  qty_received int not null default 0 check (qty_received >= 0),
  unit_cost_paise int not null check (unit_cost_paise >= 0),
  tax_rate numeric(5, 2) check (tax_rate between 0 and 100),          -- optional, informational
  line_total_paise int not null,                                       -- billed qty × unit cost
  landed_unit_cost_paise int check (landed_unit_cost_paise >= 0),      -- set when received
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (purchase_id, product_id),
  -- Billed qty is what was ordered, or what was received if more arrived (and the admin accepted it).
  check (line_total_paise = greatest(qty_ordered, qty_received) * unit_cost_paise)
);

create index purchase_items_product_idx on public.purchase_items (product_id);

create trigger purchases_touch_updated_at before update on public.purchases
  for each row execute function public.touch_updated_at();
create trigger purchase_items_touch_updated_at before update on public.purchase_items
  for each row execute function public.touch_updated_at();
create trigger purchases_audit after insert or update or delete on public.purchases
  for each row execute function public.audit_row();
create trigger purchase_items_audit after insert or update or delete on public.purchase_items
  for each row execute function public.audit_row();

alter table public.purchases enable row level security;
alter table public.purchase_items enable row level security;
create policy "Admins read purchases" on public.purchases for select using (public.is_admin());
create policy "Admins read purchase items" on public.purchase_items for select using (public.is_admin());
-- Writes only through the functions below.
revoke insert, update, delete on public.purchases, public.purchase_items from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Costing helpers (pure; mirrored in src/lib/books/purchases.js and unit-tested)
-- ---------------------------------------------------------------------------

-- Landed unit cost: the purchase's shipping minus discount is spread across lines in proportion to line value,
-- so each piece carries the same share per rupee. With a zero-value purchase it's spread per piece instead.
create function public._landed_unit_cost(p_unit_cost int, p_subtotal int, p_shipping int, p_discount int, p_total_qty int)
returns int
language sql
immutable
set search_path = ''
as $$
  select case
    when p_subtotal > 0 then round(p_unit_cost::numeric * (p_subtotal + p_shipping - p_discount) / p_subtotal)::int
    when p_total_qty > 0 then greatest(round(p_unit_cost + (p_shipping - p_discount)::numeric / p_total_qty), 0)::int
    else p_unit_cost
  end
$$;

-- Weighted average cost after receiving p_qty pieces at p_landed. Unknown (null) old cost counts as the
-- incoming landed cost, so the first receipt sets the cost.
create function public._weighted_cost(p_old_stock int, p_old_cost int, p_qty int, p_landed int)
returns int
language sql
immutable
set search_path = ''
as $$
  select case
    when p_old_cost is null or p_old_stock <= 0 then p_landed
    else round((p_old_stock::numeric * p_old_cost + p_qty::numeric * p_landed) / (p_old_stock + p_qty))::int
  end
$$;

-- Recompute a purchase's subtotal and total from its lines, optionally setting new discount / shipping / tax
-- (null = keep) in the same statement so the row's checks always see consistent numbers.
create function public._purchase_recalc(p_purchase_id uuid, p_discount int default null, p_shipping int default null, p_tax int default null)
returns void
language plpgsql
security definer set search_path = ''
as $$
declare
  v_subtotal int;
  v public.purchases;
begin
  select * into v from public.purchases where id = p_purchase_id;
  select coalesce(sum(line_total_paise), 0) into v_subtotal from public.purchase_items where purchase_id = p_purchase_id;
  if coalesce(p_discount, v.discount_paise) > v_subtotal then
    raise exception 'The discount can''t be more than the items total.' using errcode = 'P0001';
  end if;
  update public.purchases
     set subtotal_paise = v_subtotal,
         discount_paise = coalesce(p_discount, v.discount_paise),
         shipping_paise = coalesce(p_shipping, v.shipping_paise),
         tax_paise = coalesce(p_tax, v.tax_paise),
         total_paise = v_subtotal - coalesce(p_discount, v.discount_paise) + coalesce(p_shipping, v.shipping_paise) + coalesce(p_tax, v.tax_paise)
   where id = p_purchase_id;
end;
$$;

revoke execute on function public._landed_unit_cost(int, int, int, int, int) from public, anon, authenticated;
revoke execute on function public._weighted_cost(int, int, int, int) from public, anon, authenticated;
revoke execute on function public._purchase_recalc(uuid, int, int, int) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Save a purchase (create or edit) — header + lines in one transaction
-- ---------------------------------------------------------------------------
-- p_header: { order_date, expected_date, bill_number, bill_date, due_date, discount_paise, shipping_paise,
--             tax_paise, notes, bill_attachments, mark_ordered }  (dates as YYYY-MM-DD, amounts in paise)
-- p_items:  [{ product_id, qty, unit_cost_paise, tax_rate }] — or null to keep the lines (bill/notes-only edit).

create function public.books_save_purchase(p_id uuid, p_vendor_id uuid, p_header jsonb, p_items jsonb)
returns uuid
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.purchases;
  v_id uuid := p_id;
  v_terms int;
  v_locked boolean := false;
  v_item jsonb;
  v_qty int;
  v_cost int;
  v_rate numeric;
  v_product uuid;
  v_seen uuid[] := '{}';
  v_sort int := 0;
  v_bill_date date := nullif(p_header ->> 'bill_date', '')::date;
  v_attachments jsonb := coalesce(p_header -> 'bill_attachments', '[]'::jsonb);
  v_att jsonb;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  -- Attachments: Cloudinary files in the private bills folder only.
  if jsonb_typeof(v_attachments) <> 'array' or jsonb_array_length(v_attachments) > 20 then
    raise exception 'Up to 20 bill files per purchase.' using errcode = 'P0001';
  end if;
  for v_att in select * from jsonb_array_elements(v_attachments) loop
    if coalesce(v_att ->> 'publicId', '') !~ '^maati-living/bills/[A-Za-z0-9_/-]+$' then
      raise exception 'A bill file is not from the bills upload folder.' using errcode = 'P0001';
    end if;
  end loop;

  if v_id is not null then
    select * into v from public.purchases where id = v_id for update;
    if not found then
      raise exception 'Purchase not found' using errcode = 'P0002';
    end if;
    if v.status = 'cancelled' then
      raise exception 'This purchase is cancelled and can''t be changed.' using errcode = 'P0001';
    end if;
    v_locked := v.status in ('partially_received', 'received')
      or exists (select 1 from public.purchase_items where purchase_id = v_id and qty_received > 0);
    if v_locked then
      if p_items is not null then
        raise exception 'Items can''t be edited after stock has been received. Use Adjust stock and add a note.' using errcode = 'P0001';
      end if;
      if p_vendor_id is distinct from v.vendor_id
         or coalesce((p_header ->> 'discount_paise')::int, v.discount_paise) <> v.discount_paise
         or coalesce((p_header ->> 'shipping_paise')::int, v.shipping_paise) <> v.shipping_paise
         or coalesce((p_header ->> 'tax_paise')::int, v.tax_paise) <> v.tax_paise then
        raise exception 'Vendor and amounts are locked once stock has been received.' using errcode = 'P0001';
      end if;
    elsif p_items is null then
      raise exception 'Add at least one item.' using errcode = 'P0001';
    end if;
  elsif p_items is null then
    raise exception 'Add at least one item.' using errcode = 'P0001';
  end if;

  select payment_terms_days into v_terms from public.vendors
   where id = p_vendor_id and (status = 'active' or p_vendor_id = v.vendor_id);
  if v_terms is null then
    raise exception 'Choose an active vendor.' using errcode = 'P0001';
  end if;

  if coalesce((p_header ->> 'discount_paise')::int, 0) < 0 or coalesce((p_header ->> 'shipping_paise')::int, 0) < 0
     or coalesce((p_header ->> 'tax_paise')::int, 0) < 0 then
    raise exception 'Amounts can''t be negative.' using errcode = 'P0001';
  end if;

  if v_id is null then
    insert into public.purchases (number, vendor_id, order_date)
    values ('PO-' || nextval('public.purchase_number_seq'), p_vendor_id,
            coalesce(nullif(p_header ->> 'order_date', '')::date, (now() at time zone 'Asia/Kolkata')::date))
    returning id into v_id;
  end if;

  update public.purchases set
    vendor_id = p_vendor_id,
    order_date = coalesce(nullif(p_header ->> 'order_date', '')::date, order_date),
    expected_date = nullif(p_header ->> 'expected_date', '')::date,
    bill_number = nullif(btrim(p_header ->> 'bill_number'), ''),
    bill_date = v_bill_date,
    due_date = coalesce(nullif(p_header ->> 'due_date', '')::date, v_bill_date + v_terms),
    notes = nullif(btrim(p_header ->> 'notes'), ''),
    bill_attachments = v_attachments,
    status = case when status = 'draft' and coalesce((p_header ->> 'mark_ordered')::boolean, false) then 'ordered' else status end,
    ordered_at = case when status = 'draft' and coalesce((p_header ->> 'mark_ordered')::boolean, false) then now() else ordered_at end
  where id = v_id;

  if p_items is not null then
    if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
      raise exception 'Add at least one item.' using errcode = 'P0001';
    end if;
    if jsonb_array_length(p_items) > 200 then
      raise exception 'Up to 200 items per purchase.' using errcode = 'P0001';
    end if;
    delete from public.purchase_items where purchase_id = v_id;  -- nothing received yet, so lines are free to replace
    for v_item in select * from jsonb_array_elements(p_items) loop
      v_product := (v_item ->> 'product_id')::uuid;
      v_qty := (v_item ->> 'qty')::int;
      v_cost := (v_item ->> 'unit_cost_paise')::int;
      v_rate := nullif(v_item ->> 'tax_rate', '')::numeric;
      if v_product is null or not exists (select 1 from public.products where id = v_product) then
        raise exception 'An item''s product no longer exists.' using errcode = 'P0001';
      end if;
      if v_product = any (v_seen) then
        raise exception '% is in the list twice — combine them into one line.', (select name from public.products where id = v_product) using errcode = 'P0001';
      end if;
      v_seen := v_seen || v_product;
      if v_qty is null or v_qty <= 0 or v_qty > 100000 then
        raise exception 'Quantity for % must be a whole number above 0.', (select name from public.products where id = v_product) using errcode = 'P0001';
      end if;
      if v_cost is null or v_cost < 0 then
        raise exception 'Enter the cost per piece for %.', (select name from public.products where id = v_product) using errcode = 'P0001';
      end if;
      insert into public.purchase_items (purchase_id, product_id, qty_ordered, unit_cost_paise, tax_rate, line_total_paise, sort_order)
      values (v_id, v_product, v_qty, v_cost, v_rate, v_qty * v_cost, v_sort);
      v_sort := v_sort + 1;
    end loop;
  end if;

  perform public._purchase_recalc(v_id, (p_header ->> 'discount_paise')::int, (p_header ->> 'shipping_paise')::int, (p_header ->> 'tax_paise')::int);
  return v_id;
end;
$$;

revoke execute on function public.books_save_purchase(uuid, uuid, jsonb, jsonb) from public, anon;
grant execute on function public.books_save_purchase(uuid, uuid, jsonb, jsonb) to authenticated; -- is_admin() inside

-- ---------------------------------------------------------------------------
-- 5. Status changes
-- ---------------------------------------------------------------------------

create function public.books_mark_purchase_ordered(p_id uuid)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  update public.purchases set status = 'ordered', ordered_at = now() where id = p_id and status = 'draft';
  if not found then
    raise exception 'Only a draft can be marked as ordered.' using errcode = 'P0001';
  end if;
end;
$$;

create function public.books_cancel_purchase(p_id uuid, p_reason text)
returns void
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.purchases;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'Please give a short reason for cancelling.' using errcode = 'P0001';
  end if;
  select * into v from public.purchases where id = p_id for update;
  if not found then
    raise exception 'Purchase not found' using errcode = 'P0002';
  end if;
  if v.status not in ('draft', 'ordered') or exists (select 1 from public.purchase_items where purchase_id = p_id and qty_received > 0) then
    raise exception 'Stock has already been received on this purchase, so it can''t be cancelled. Use Adjust stock and add a note.' using errcode = 'P0001';
  end if;
  update public.purchases set status = 'cancelled', cancelled_at = now(), cancelled_reason = btrim(p_reason) where id = p_id;
end;
$$;

revoke execute on function public.books_mark_purchase_ordered(uuid) from public, anon;
grant execute on function public.books_mark_purchase_ordered(uuid) to authenticated;
revoke execute on function public.books_cancel_purchase(uuid, text) from public, anon;
grant execute on function public.books_cancel_purchase(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 6. Receive items
-- ---------------------------------------------------------------------------
-- p_lines: [{ item_id, qty }] — qty pieces arriving now per line (0 / missing = none for that line).

create function public.books_receive_purchase(p_id uuid, p_lines jsonb, p_note text default null, p_allow_over boolean default false)
returns text
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.purchases;
  v_line jsonb;
  v_item public.purchase_items;
  v_qty int;
  v_any boolean := false;
  v_seen uuid[] := '{}';
  v_total_qty int;
  v_landed int;
  v_stock int;
  v_cost int;
  v_status text;
  r record;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  select * into v from public.purchases where id = p_id for update;
  if not found then
    raise exception 'Purchase not found' using errcode = 'P0002';
  end if;
  if v.status not in ('draft', 'ordered', 'partially_received') then
    raise exception 'This purchase is % — nothing left to receive.', replace(v.status, '_', ' ') using errcode = 'P0001';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    raise exception 'Enter the quantities received.' using errcode = 'P0001';
  end if;

  -- Pass 1: validate and record received quantities (billed qty grows if more arrived than ordered).
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_qty := coalesce(nullif(v_line ->> 'qty', '')::int, 0);
    continue when v_qty = 0;
    if v_qty < 0 or v_qty > 100000 then
      raise exception 'Received quantities must be whole numbers, 0 or more.' using errcode = 'P0001';
    end if;
    select * into v_item from public.purchase_items where id = (v_line ->> 'item_id')::uuid and purchase_id = p_id for update;
    if not found then
      raise exception 'An item doesn''t belong to this purchase.' using errcode = 'P0001';
    end if;
    if v_item.id = any (v_seen) then
      raise exception 'An item is listed twice.' using errcode = 'P0001';
    end if;
    v_seen := v_seen || v_item.id;
    if v_item.qty_received + v_qty > v_item.qty_ordered and not coalesce(p_allow_over, false) then
      raise exception 'More than ordered for % (ordered %, receiving % in total). Confirm the extra pieces to continue.',
        (select name from public.products where id = v_item.product_id), v_item.qty_ordered, v_item.qty_received + v_qty
        using errcode = 'P0001', hint = 'over_receive';
    end if;
    update public.purchase_items
       set qty_received = qty_received + v_qty,
           line_total_paise = greatest(qty_ordered, qty_received + v_qty) * unit_cost_paise
     where id = v_item.id;
    v_any := true;
  end loop;
  if not v_any then
    raise exception 'Enter how many pieces arrived for at least one item.' using errcode = 'P0001';
  end if;

  perform public._purchase_recalc(p_id);
  select * into v from public.purchases where id = p_id;
  select coalesce(sum(greatest(qty_ordered, qty_received)), 0) into v_total_qty from public.purchase_items where purchase_id = p_id;

  -- Pass 2: stock in at landed cost, weighted average cost, vendor's last price.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_qty := coalesce(nullif(v_line ->> 'qty', '')::int, 0);
    continue when v_qty = 0;
    select * into v_item from public.purchase_items where id = (v_line ->> 'item_id')::uuid;
    v_landed := public._landed_unit_cost(v_item.unit_cost_paise, v.subtotal_paise, v.shipping_paise, v.discount_paise, v_total_qty);

    select stock, cost_price_paise into v_stock, v_cost from public.products where id = v_item.product_id for update;
    update public.products set cost_price_paise = public._weighted_cost(v_stock, v_cost, v_qty, v_landed) where id = v_item.product_id;
    perform public._stock_move(v_item.product_id, v_qty, 'purchase_receipt', 'purchase', p_id, v_landed,
      coalesce(nullif(btrim(p_note), ''), 'Received on ' || v.number));
    update public.purchase_items set landed_unit_cost_paise = v_landed where id = v_item.id;

    insert into public.vendor_products (vendor_id, product_id, last_cost_paise)
    values (v.vendor_id, v_item.product_id, v_item.unit_cost_paise)
    on conflict (vendor_id, product_id) do update set last_cost_paise = excluded.last_cost_paise;
  end loop;

  v_status := case
    when not exists (select 1 from public.purchase_items where purchase_id = p_id and qty_received < qty_ordered) then 'received'
    else 'partially_received'
  end;
  update public.purchases
     set status = v_status,
         ordered_at = coalesce(ordered_at, now()),
         received_at = case when v_status = 'received' then now() else received_at end
   where id = p_id;
  return v_status;
end;
$$;

revoke execute on function public.books_receive_purchase(uuid, jsonb, text, boolean) from public, anon;
grant execute on function public.books_receive_purchase(uuid, jsonb, text, boolean) to authenticated; -- is_admin() inside

-- ===========================================================================
-- 0009_purchase_cost_positive.sql
-- ===========================================================================

-- Maati Living — Books, Phase 2 fix: purchase lines must cost more than ₹0.
-- Run in Supabase → SQL Editor after 0008 (backup first; dev/test project first).
-- Replaces one function only. Nothing is dropped; existing purchases (e.g. a cancelled ₹0 one) are left as they are.
-- Free samples aren't purchases: add them with Inventory → Adjust stock → "Sample / gift".

create or replace function public.books_save_purchase(p_id uuid, p_vendor_id uuid, p_header jsonb, p_items jsonb)
returns uuid
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.purchases;
  v_id uuid := p_id;
  v_terms int;
  v_locked boolean := false;
  v_item jsonb;
  v_qty int;
  v_cost int;
  v_rate numeric;
  v_product uuid;
  v_seen uuid[] := '{}';
  v_sort int := 0;
  v_bill_date date := nullif(p_header ->> 'bill_date', '')::date;
  v_attachments jsonb := coalesce(p_header -> 'bill_attachments', '[]'::jsonb);
  v_att jsonb;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  -- Attachments: Cloudinary files in the private bills folder only.
  if jsonb_typeof(v_attachments) <> 'array' or jsonb_array_length(v_attachments) > 20 then
    raise exception 'Up to 20 bill files per purchase.' using errcode = 'P0001';
  end if;
  for v_att in select * from jsonb_array_elements(v_attachments) loop
    if coalesce(v_att ->> 'publicId', '') !~ '^maati-living/bills/[A-Za-z0-9_/-]+$' then
      raise exception 'A bill file is not from the bills upload folder.' using errcode = 'P0001';
    end if;
  end loop;

  if v_id is not null then
    select * into v from public.purchases where id = v_id for update;
    if not found then
      raise exception 'Purchase not found' using errcode = 'P0002';
    end if;
    if v.status = 'cancelled' then
      raise exception 'This purchase is cancelled and can''t be changed.' using errcode = 'P0001';
    end if;
    v_locked := v.status in ('partially_received', 'received')
      or exists (select 1 from public.purchase_items where purchase_id = v_id and qty_received > 0);
    if v_locked then
      if p_items is not null then
        raise exception 'Items can''t be edited after stock has been received. Use Adjust stock and add a note.' using errcode = 'P0001';
      end if;
      if p_vendor_id is distinct from v.vendor_id
         or coalesce((p_header ->> 'discount_paise')::int, v.discount_paise) <> v.discount_paise
         or coalesce((p_header ->> 'shipping_paise')::int, v.shipping_paise) <> v.shipping_paise
         or coalesce((p_header ->> 'tax_paise')::int, v.tax_paise) <> v.tax_paise then
        raise exception 'Vendor and amounts are locked once stock has been received.' using errcode = 'P0001';
      end if;
    elsif p_items is null then
      raise exception 'Add at least one item.' using errcode = 'P0001';
    end if;
  elsif p_items is null then
    raise exception 'Add at least one item.' using errcode = 'P0001';
  end if;

  select payment_terms_days into v_terms from public.vendors
   where id = p_vendor_id and (status = 'active' or p_vendor_id = v.vendor_id);
  if v_terms is null then
    raise exception 'Choose an active vendor.' using errcode = 'P0001';
  end if;

  if coalesce((p_header ->> 'discount_paise')::int, 0) < 0 or coalesce((p_header ->> 'shipping_paise')::int, 0) < 0
     or coalesce((p_header ->> 'tax_paise')::int, 0) < 0 then
    raise exception 'Amounts can''t be negative.' using errcode = 'P0001';
  end if;

  if v_id is null then
    insert into public.purchases (number, vendor_id, order_date)
    values ('PO-' || nextval('public.purchase_number_seq'), p_vendor_id,
            coalesce(nullif(p_header ->> 'order_date', '')::date, (now() at time zone 'Asia/Kolkata')::date))
    returning id into v_id;
  end if;

  update public.purchases set
    vendor_id = p_vendor_id,
    order_date = coalesce(nullif(p_header ->> 'order_date', '')::date, order_date),
    expected_date = nullif(p_header ->> 'expected_date', '')::date,
    bill_number = nullif(btrim(p_header ->> 'bill_number'), ''),
    bill_date = v_bill_date,
    due_date = coalesce(nullif(p_header ->> 'due_date', '')::date, v_bill_date + v_terms),
    notes = nullif(btrim(p_header ->> 'notes'), ''),
    bill_attachments = v_attachments,
    status = case when status = 'draft' and coalesce((p_header ->> 'mark_ordered')::boolean, false) then 'ordered' else status end,
    ordered_at = case when status = 'draft' and coalesce((p_header ->> 'mark_ordered')::boolean, false) then now() else ordered_at end
  where id = v_id;

  if p_items is not null then
    if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
      raise exception 'Add at least one item.' using errcode = 'P0001';
    end if;
    if jsonb_array_length(p_items) > 200 then
      raise exception 'Up to 200 items per purchase.' using errcode = 'P0001';
    end if;
    delete from public.purchase_items where purchase_id = v_id;  -- nothing received yet, so lines are free to replace
    for v_item in select * from jsonb_array_elements(p_items) loop
      v_product := (v_item ->> 'product_id')::uuid;
      v_qty := (v_item ->> 'qty')::int;
      v_cost := (v_item ->> 'unit_cost_paise')::int;
      v_rate := nullif(v_item ->> 'tax_rate', '')::numeric;
      if v_product is null or not exists (select 1 from public.products where id = v_product) then
        raise exception 'An item''s product no longer exists.' using errcode = 'P0001';
      end if;
      if v_product = any (v_seen) then
        raise exception '% is in the list twice — combine them into one line.', (select name from public.products where id = v_product) using errcode = 'P0001';
      end if;
      v_seen := v_seen || v_product;
      if v_qty is null or v_qty <= 0 or v_qty > 100000 then
        raise exception 'Quantity for % must be a whole number above 0.', (select name from public.products where id = v_product) using errcode = 'P0001';
      end if;
      if v_cost is null or v_cost <= 0 then
        raise exception 'Cost per piece for % must be more than ₹0. For free samples, use Adjust stock → Sample instead.', (select name from public.products where id = v_product) using errcode = 'P0001';
      end if;
      insert into public.purchase_items (purchase_id, product_id, qty_ordered, unit_cost_paise, tax_rate, line_total_paise, sort_order)
      values (v_id, v_product, v_qty, v_cost, v_rate, v_qty * v_cost, v_sort);
      v_sort := v_sort + 1;
    end loop;
  end if;

  perform public._purchase_recalc(v_id, (p_header ->> 'discount_paise')::int, (p_header ->> 'shipping_paise')::int, (p_header ->> 'tax_paise')::int);
  return v_id;
end;
$$;

-- ===========================================================================
-- 0010_books_payments.sql
-- ===========================================================================

-- Maati Living — Books, Phase 3: vendor payments, allocation to bills, payables.
-- Run in Supabase → SQL Editor after 0009. TAKE A BACKUP FIRST and run on the dev/test project first.
-- Nothing existing is dropped or rewritten: two new tables, new functions, and two guard triggers.
--
-- Rules
--   * A payment is written only through the functions below (one transaction each, RAISE on any problem).
--   * Allocation: a payment covers one or more open items of its vendor — the opening balance (purchase_id null)
--     and payable purchases (received / partly received / billed, not cancelled). Never more than an item's
--     balance, never more than the payment. Whatever isn't allocated is an advance with the vendor.
--   * Auto-allocation (when no allocation is given): opening balance first, then bills oldest first by
--     (bill date, else order date), then created_at. Mirrored in src/lib/books/payments.js (a DB test compares).
--   * Voiding keeps the payment and its allocations for the record; only active payments count anywhere.
--   * Vendor balance = opening balance + payable purchase totals − active payments.
--   * Guards: a purchase that has payments allocated can't be cancelled, lose its bill / payable status, or drop
--     below the amount paid; a vendor's opening balance can't drop below what's been paid against it.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------

create sequence public.payment_number_seq start 1001;
revoke all on sequence public.payment_number_seq from public, anon, authenticated;

create table public.vendor_payments (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,                        -- PAY-1001, PAY-1002, …
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  amount_paise int not null check (amount_paise > 0),
  paid_on date not null,
  method text not null check (method in ('upi', 'bank', 'cash', 'other')),
  reference text check (char_length(reference) <= 80),  -- UTR / cheque no. etc.
  attachments jsonb not null default '[]'::jsonb check (jsonb_typeof(attachments) = 'array'),
  notes text check (char_length(notes) <= 2000),
  status text not null default 'active' check (status in ('active', 'voided')),
  void_reason text,
  voided_at timestamptz,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (status <> 'voided' or (void_reason is not null and voided_at is not null))
);

create index vendor_payments_vendor_idx on public.vendor_payments (vendor_id, paid_on desc);
create index vendor_payments_paid_on_idx on public.vendor_payments (paid_on desc);

create table public.vendor_payment_allocations (
  id uuid primary key default gen_random_uuid(),
  payment_id uuid not null references public.vendor_payments (id) on delete restrict,
  purchase_id uuid references public.purchases (id) on delete restrict,   -- null = the vendor's opening balance
  amount_paise int not null check (amount_paise > 0),
  created_at timestamptz not null default now()
);

create unique index vendor_payment_allocations_bill_idx on public.vendor_payment_allocations (payment_id, purchase_id) where purchase_id is not null;
create unique index vendor_payment_allocations_opening_idx on public.vendor_payment_allocations (payment_id) where purchase_id is null;
create index vendor_payment_allocations_purchase_idx on public.vendor_payment_allocations (purchase_id);

create trigger vendor_payments_touch_updated_at before update on public.vendor_payments
  for each row execute function public.touch_updated_at();
create trigger vendor_payments_audit after insert or update or delete on public.vendor_payments
  for each row execute function public.audit_row();
create trigger vendor_payment_allocations_audit after insert or update or delete on public.vendor_payment_allocations
  for each row execute function public.audit_row();

alter table public.vendor_payments enable row level security;
alter table public.vendor_payment_allocations enable row level security;
create policy "Admins read vendor payments" on public.vendor_payments for select using (public.is_admin());
create policy "Admins read payment allocations" on public.vendor_payment_allocations for select using (public.is_admin());
-- Writes only through the functions below.
revoke insert, update, delete on public.vendor_payments, public.vendor_payment_allocations from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Helpers (internal)
-- ---------------------------------------------------------------------------

-- "₹1500" / "₹1500.50" for error messages.
create function public._rupees(p_paise bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select '₹' || case when p_paise % 100 = 0 then (p_paise / 100)::text else to_char(p_paise / 100.0, 'FM999999999990.00') end
$$;

-- Same rule as isPayable() in src/lib/books/purchases.js.
create function public._purchase_is_payable(p_status text, p_bill_number text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_status <> 'cancelled' and (p_status in ('partially_received', 'received') or p_bill_number is not null)
$$;

-- Paid so far on a purchase (active payments only), optionally leaving one payment out.
create function public._purchase_paid(p_purchase_id uuid, p_except_payment uuid default null)
returns bigint
language sql
stable
security definer set search_path = ''
as $$
  select coalesce(sum(a.amount_paise), 0)::bigint
    from public.vendor_payment_allocations a
    join public.vendor_payments p on p.id = a.payment_id
   where a.purchase_id = p_purchase_id and p.status = 'active' and p.id is distinct from p_except_payment
$$;

-- Paid so far against a vendor's opening balance (active payments only), optionally leaving one payment out.
create function public._opening_paid(p_vendor_id uuid, p_except_payment uuid default null)
returns bigint
language sql
stable
security definer set search_path = ''
as $$
  select coalesce(sum(a.amount_paise), 0)::bigint
    from public.vendor_payment_allocations a
    join public.vendor_payments p on p.id = a.payment_id
   where a.purchase_id is null and p.vendor_id = p_vendor_id and p.status = 'active' and p.id is distinct from p_except_payment
$$;

-- Write a payment's allocations (the caller has removed any old ones and locked the vendor row).
-- p_allocations: [{ purchase_id (null = opening balance), amount_paise }], or null = auto, oldest first.
create function public._apply_payment_allocations(p_payment_id uuid, p_allocations jsonb)
returns void
language plpgsql
security definer set search_path = ''
as $$
declare
  v_pay public.vendor_payments;
  v_vendor public.vendors;
  v_left bigint;
  v_balance bigint;
  v_take bigint;
  v_line jsonb;
  v_amount int;
  v_purchase uuid;
  v_seen text[] := '{}';
  v_key text;
  r record;
begin
  select * into v_pay from public.vendor_payments where id = p_payment_id;
  select * into v_vendor from public.vendors where id = v_pay.vendor_id;
  v_left := v_pay.amount_paise;

  if p_allocations is null then
    -- Opening balance first.
    v_balance := greatest(v_vendor.opening_balance_paise, 0) - public._opening_paid(v_vendor.id, p_payment_id);
    if v_balance > 0 and v_left > 0 then
      v_take := least(v_left, v_balance);
      insert into public.vendor_payment_allocations (payment_id, purchase_id, amount_paise) values (p_payment_id, null, v_take);
      v_left := v_left - v_take;
    end if;
    -- Then bills, oldest first.
    for r in
      select id, total_paise from public.purchases
       where vendor_id = v_vendor.id and public._purchase_is_payable(status, bill_number)
       order by coalesce(bill_date, order_date), created_at
       for update
    loop
      exit when v_left <= 0;
      v_balance := r.total_paise - public._purchase_paid(r.id, p_payment_id);
      continue when v_balance <= 0;
      v_take := least(v_left, v_balance);
      insert into public.vendor_payment_allocations (payment_id, purchase_id, amount_paise) values (p_payment_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
    return;
  end if;

  if jsonb_typeof(p_allocations) <> 'array' then
    raise exception 'The allocation couldn''t be read. Please try again.' using errcode = 'P0001';
  end if;
  if jsonb_array_length(p_allocations) > 200 then
    raise exception 'Up to 200 bills per payment.' using errcode = 'P0001';
  end if;

  for v_line in select * from jsonb_array_elements(p_allocations) loop
    v_amount := coalesce(nullif(v_line ->> 'amount_paise', '')::int, 0);
    continue when v_amount = 0;
    if v_amount < 0 then
      raise exception 'Allocated amounts must be more than ₹0.' using errcode = 'P0001';
    end if;
    v_purchase := nullif(v_line ->> 'purchase_id', '')::uuid;
    v_key := coalesce(v_purchase::text, 'opening');
    if v_key = any (v_seen) then
      raise exception 'A bill is listed twice in the allocation.' using errcode = 'P0001';
    end if;
    v_seen := v_seen || v_key;

    if v_purchase is null then
      v_balance := greatest(v_vendor.opening_balance_paise, 0) - public._opening_paid(v_vendor.id, p_payment_id);
      if v_amount > v_balance then
        raise exception 'Only % of the opening balance is still to pay.', public._rupees(greatest(v_balance, 0)) using errcode = 'P0001';
      end if;
    else
      select * into r from public.purchases where id = v_purchase and vendor_id = v_vendor.id for update;
      if not found then
        raise exception 'A bill in the allocation isn''t from this vendor.' using errcode = 'P0001';
      end if;
      if not public._purchase_is_payable(r.status, r.bill_number) then
        raise exception '% isn''t a bill yet (nothing received and no bill number), so it can''t be paid against.', r.number using errcode = 'P0001';
      end if;
      v_balance := r.total_paise - public._purchase_paid(v_purchase, p_payment_id);
      if v_amount > v_balance then
        raise exception 'Only % is still to pay on %.', public._rupees(greatest(v_balance, 0)), r.number using errcode = 'P0001';
      end if;
    end if;

    if v_amount > v_left then
      raise exception 'The allocation adds up to more than the payment (%).', public._rupees(v_pay.amount_paise) using errcode = 'P0001';
    end if;
    insert into public.vendor_payment_allocations (payment_id, purchase_id, amount_paise) values (p_payment_id, v_purchase, v_amount);
    v_left := v_left - v_amount;
  end loop;
end;
$$;

revoke execute on function public._rupees(bigint) from public, anon, authenticated;
revoke execute on function public._purchase_is_payable(text, text) from public, anon, authenticated;
revoke execute on function public._purchase_paid(uuid, uuid) from public, anon, authenticated;
revoke execute on function public._opening_paid(uuid, uuid) from public, anon, authenticated;
revoke execute on function public._apply_payment_allocations(uuid, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Record, re-allocate, void
-- ---------------------------------------------------------------------------
-- p_payment: { amount_paise, paid_on (YYYY-MM-DD), method, reference, notes, attachments }

create function public.books_record_payment(p_vendor_id uuid, p_payment jsonb, p_allocations jsonb default null)
returns uuid
language plpgsql
security definer set search_path = ''
as $$
declare
  v_vendor public.vendors;
  v_id uuid;
  v_amount int := nullif(p_payment ->> 'amount_paise', '')::int;
  v_paid_on date := nullif(p_payment ->> 'paid_on', '')::date;
  v_method text := p_payment ->> 'method';
  v_attachments jsonb := coalesce(p_payment -> 'attachments', '[]'::jsonb);
  v_att jsonb;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;

  select * into v_vendor from public.vendors where id = p_vendor_id for update;  -- one payment per vendor at a time
  if not found then
    raise exception 'Choose a vendor.' using errcode = 'P0001';
  end if;
  if v_vendor.status <> 'active' then
    raise exception '% is archived. Restore the vendor to record a payment.', v_vendor.name using errcode = 'P0001';
  end if;
  if v_amount is null or v_amount <= 0 or v_amount > 1000000000 then
    raise exception 'Enter the amount paid (more than ₹0).' using errcode = 'P0001';
  end if;
  if v_paid_on is null then
    raise exception 'Enter the date it was paid.' using errcode = 'P0001';
  end if;
  if v_paid_on > (now() at time zone 'Asia/Kolkata')::date then
    raise exception 'The payment date can''t be in the future.' using errcode = 'P0001';
  end if;
  if v_method is null or v_method not in ('upi', 'bank', 'cash', 'other') then
    raise exception 'Choose how it was paid.' using errcode = 'P0001';
  end if;
  if jsonb_typeof(v_attachments) <> 'array' or jsonb_array_length(v_attachments) > 10 then
    raise exception 'Up to 10 proof files per payment.' using errcode = 'P0001';
  end if;
  for v_att in select * from jsonb_array_elements(v_attachments) loop
    if coalesce(v_att ->> 'publicId', '') !~ '^maati-living/bills/[A-Za-z0-9_/-]+$' then
      raise exception 'A proof file is not from the private upload folder.' using errcode = 'P0001';
    end if;
  end loop;

  insert into public.vendor_payments (number, vendor_id, amount_paise, paid_on, method, reference, notes, attachments)
  values ('PAY-' || nextval('public.payment_number_seq'), v_vendor.id, v_amount, v_paid_on, v_method,
          nullif(btrim(left(p_payment ->> 'reference', 80)), ''), nullif(btrim(p_payment ->> 'notes'), ''), v_attachments)
  returning id into v_id;

  perform public._apply_payment_allocations(v_id, p_allocations);
  return v_id;
end;
$$;

-- Change which bills a payment covers (e.g. apply an advance to a bill that came later).
create function public.books_set_payment_allocations(p_payment_id uuid, p_allocations jsonb default null)
returns void
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.vendor_payments;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  select * into v from public.vendor_payments where id = p_payment_id for update;
  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if v.status <> 'active' then
    raise exception '% is voided and can''t be changed.', v.number using errcode = 'P0001';
  end if;
  perform 1 from public.vendors where id = v.vendor_id for update;
  delete from public.vendor_payment_allocations where payment_id = p_payment_id;
  perform public._apply_payment_allocations(p_payment_id, p_allocations);
end;
$$;

create function public.books_void_payment(p_id uuid, p_reason text)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'Please give a short reason for voiding.' using errcode = 'P0001';
  end if;
  update public.vendor_payments set status = 'voided', void_reason = left(btrim(p_reason), 300), voided_at = now()
   where id = p_id and status = 'active';
  if not found then
    raise exception 'Only an active payment can be voided.' using errcode = 'P0001';
  end if;
end;
$$;

revoke execute on function public.books_record_payment(uuid, jsonb, jsonb) from public, anon;
grant execute on function public.books_record_payment(uuid, jsonb, jsonb) to authenticated;            -- is_admin() inside
revoke execute on function public.books_set_payment_allocations(uuid, jsonb) from public, anon;
grant execute on function public.books_set_payment_allocations(uuid, jsonb) to authenticated;          -- is_admin() inside
revoke execute on function public.books_void_payment(uuid, text) from public, anon;
grant execute on function public.books_void_payment(uuid, text) to authenticated;                      -- is_admin() inside

-- ---------------------------------------------------------------------------
-- 4. Guards: paid bills and paid opening balances stay consistent
-- ---------------------------------------------------------------------------

create function public.purchases_guard_payments()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
declare
  v_paid bigint := public._purchase_paid(new.id);
begin
  if v_paid > 0 then
    if new.status = 'cancelled' then
      raise exception '% of payments is allocated to %. Void the payment or move it to another bill first.', public._rupees(v_paid), new.number using errcode = 'P0001';
    end if;
    if not public._purchase_is_payable(new.status, new.bill_number) then
      raise exception '% has payments against it, so it needs its bill number.', new.number using errcode = 'P0001';
    end if;
    if new.total_paise < v_paid then
      raise exception 'The total of % can''t go below what''s already been paid (%).', new.number, public._rupees(v_paid) using errcode = 'P0001';
    end if;
  end if;
  return null;
end;
$$;

create trigger purchases_guard_payments after update of status, bill_number, total_paise on public.purchases
  for each row execute function public.purchases_guard_payments();

create function public.vendors_guard_opening_paid()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
declare
  v_paid bigint := public._opening_paid(new.id);
begin
  if v_paid > greatest(new.opening_balance_paise, 0) then
    raise exception 'Payments of % are allocated to the opening balance, so it can''t be less than that.', public._rupees(v_paid) using errcode = 'P0001';
  end if;
  return null;
end;
$$;

create trigger vendors_guard_opening_paid after update of opening_balance_paise on public.vendors
  for each row execute function public.vendors_guard_opening_paid();

-- ===========================================================================
-- 0011_books_expenses.sql
-- ===========================================================================

-- Maati Living — Books, Phase 4: expenses, categories, recurring reminders.
-- Run in Supabase → SQL Editor after 0010. TAKE A BACKUP FIRST and run on the dev/test project first.
-- Nothing existing is dropped or rewritten: two new tables, a sequence and new functions.
--
-- Rules
--   * Expenses are written only through the functions below (RAISE on any problem). Active ones can be edited
--     (audit_log keeps before/after); voided ones stay listed with the reason and count nowhere. Never deleted.
--   * Categories: admins add / rename / reorder / archive directly (RLS). Never deleted.
--   * Recurring: an expense marked recurring is the "template". When its next_due_on comes, the dashboard shows a
--     reminder; the admin confirms (posts a new expense, amount editable) or skips. Nothing is posted on its own.
--     Next dates step from the template's first date (31 Jan → 28 Feb → 31 Mar), mirrored in src/lib/books/expenses.js.

-- ---------------------------------------------------------------------------
-- 1. Categories
-- ---------------------------------------------------------------------------

create table public.expense_categories (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(btrim(name)) between 2 and 60),
  sort_order int not null default 0,
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index expense_categories_name_idx on public.expense_categories (lower(btrim(name)));

create trigger expense_categories_touch_updated_at before update on public.expense_categories
  for each row execute function public.touch_updated_at();
create trigger expense_categories_audit after insert or update or delete on public.expense_categories
  for each row execute function public.audit_row();

alter table public.expense_categories enable row level security;
create policy "Admins read expense categories" on public.expense_categories for select using (public.is_admin());
create policy "Admins add expense categories" on public.expense_categories for insert with check (public.is_admin());
create policy "Admins edit expense categories" on public.expense_categories for update using (public.is_admin()) with check (public.is_admin());
-- No delete policy: categories are archived, never deleted.

insert into public.expense_categories (name, sort_order) values
  ('Packaging', 10), ('Courier & shipping', 20), ('Ads & marketing', 30), ('Photography', 40),
  ('Website & software', 50), ('Travel', 60), ('Rent', 70), ('Utilities', 80),
  ('Bank & payment charges', 90), ('Miscellaneous', 100);

-- ---------------------------------------------------------------------------
-- 2. Expenses
-- ---------------------------------------------------------------------------

create sequence public.expense_number_seq start 1001;
revoke all on sequence public.expense_number_seq from public, anon, authenticated;

create table public.expenses (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,                                   -- EXP-1001, EXP-1002, …
  category_id uuid not null references public.expense_categories (id) on delete restrict,
  amount_paise int not null check (amount_paise > 0),           -- what was paid, tax included
  tax_paise int not null default 0 check (tax_paise >= 0),      -- optional: GST part of the amount
  spent_on date not null,
  paid_via text not null check (paid_via in ('upi', 'bank', 'cash', 'card', 'other')),
  vendor_id uuid references public.vendors (id) on delete restrict,
  description text check (char_length(description) <= 300),
  attachments jsonb not null default '[]'::jsonb check (jsonb_typeof(attachments) = 'array'),
  is_recurring boolean not null default false,
  recurrence text check (recurrence in ('monthly', 'yearly')),
  next_due_on date,
  recurring_source_id uuid references public.expenses (id) on delete restrict,  -- the template this was posted from
  status text not null default 'active' check (status in ('active', 'voided')),
  void_reason text,
  voided_at timestamptz,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (tax_paise <= amount_paise),
  check (not is_recurring or (recurrence is not null and next_due_on is not null)),
  check (status <> 'voided' or (void_reason is not null and voided_at is not null))
);

create index expenses_spent_on_idx on public.expenses (spent_on desc);
create index expenses_category_idx on public.expenses (category_id, spent_on desc);
create index expenses_due_idx on public.expenses (next_due_on) where is_recurring;
create index expenses_source_idx on public.expenses (recurring_source_id);

create trigger expenses_touch_updated_at before update on public.expenses
  for each row execute function public.touch_updated_at();
create trigger expenses_audit after insert or update or delete on public.expenses
  for each row execute function public.audit_row();

alter table public.expenses enable row level security;
create policy "Admins read expenses" on public.expenses for select using (public.is_admin());
-- Writes only through the functions below.
revoke insert, update, delete on public.expenses from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Helpers (internal)
-- ---------------------------------------------------------------------------

-- First date after p_after in the series p_start + n months/years (n ≥ 1), counted from the start so month ends
-- don't drift (31 Jan → 28 Feb → 31 Mar). Same as nextDueDate() in src/lib/books/expenses.js.
create function public._next_due(p_start date, p_after date, p_recurrence text)
returns date
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_step interval := case p_recurrence when 'yearly' then interval '1 year' else interval '1 month' end;
  v_n int := 1;
  v_date date;
begin
  loop
    v_date := (p_start + v_n * v_step)::date;
    exit when v_date > p_after;
    v_n := v_n + 1;
  end loop;
  return v_date;
end;
$$;

revoke execute on function public._next_due(date, date, text) from public, anon, authenticated;

-- Validates and normalises the shared expense fields. Raises on anything wrong.
-- p: { category_id, amount_paise, tax_paise, spent_on, paid_via, vendor_id, description, attachments }
create function public._check_expense(p jsonb, p_old public.expenses default null)
returns void
language plpgsql
stable
security definer set search_path = ''
as $$
declare
  v_amount int := nullif(p ->> 'amount_paise', '')::int;
  v_tax int := coalesce(nullif(p ->> 'tax_paise', '')::int, 0);
  v_spent date := nullif(p ->> 'spent_on', '')::date;
  v_category uuid := nullif(p ->> 'category_id', '')::uuid;
  v_vendor uuid := nullif(p ->> 'vendor_id', '')::uuid;
  v_attachments jsonb := coalesce(p -> 'attachments', '[]'::jsonb);
  v_att jsonb;
begin
  if v_category is null or not exists (select 1 from public.expense_categories where id = v_category
      and (status = 'active' or v_category = p_old.category_id)) then
    raise exception 'Choose a category.' using errcode = 'P0001';
  end if;
  if v_amount is null or v_amount <= 0 or v_amount > 1000000000 then
    raise exception 'Enter the amount spent (more than ₹0).' using errcode = 'P0001';
  end if;
  if v_tax < 0 or v_tax > v_amount then
    raise exception 'Tax can''t be more than the amount.' using errcode = 'P0001';
  end if;
  if v_spent is null then
    raise exception 'Enter the date it was spent.' using errcode = 'P0001';
  end if;
  if v_spent > (now() at time zone 'Asia/Kolkata')::date then
    raise exception 'The date can''t be in the future.' using errcode = 'P0001';
  end if;
  if coalesce(p ->> 'paid_via', '') not in ('upi', 'bank', 'cash', 'card', 'other') then
    raise exception 'Choose how it was paid.' using errcode = 'P0001';
  end if;
  if v_vendor is not null and not exists (select 1 from public.vendors where id = v_vendor
      and (status = 'active' or v_vendor = p_old.vendor_id)) then
    raise exception 'Choose an active vendor, or leave it blank.' using errcode = 'P0001';
  end if;
  if char_length(coalesce(p ->> 'description', '')) > 300 then
    raise exception 'The description is too long (300 characters max).' using errcode = 'P0001';
  end if;
  if jsonb_typeof(v_attachments) <> 'array' or jsonb_array_length(v_attachments) > 10 then
    raise exception 'Up to 10 receipt files per expense.' using errcode = 'P0001';
  end if;
  for v_att in select * from jsonb_array_elements(v_attachments) loop
    if coalesce(v_att ->> 'publicId', '') !~ '^maati-living/bills/[A-Za-z0-9_/-]+$' then
      raise exception 'A receipt file is not from the private upload folder.' using errcode = 'P0001';
    end if;
  end loop;
end;
$$;

revoke execute on function public._check_expense(jsonb, public.expenses) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Save (create / edit), void, recurring
-- ---------------------------------------------------------------------------
-- p_data: the fields above + { is_recurring, recurrence, next_due_on } (next_due_on blank = one step after spent_on)

create function public.books_save_expense(p_id uuid, p_data jsonb)
returns uuid
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.expenses;
  v_id uuid := p_id;
  v_spent date := nullif(p_data ->> 'spent_on', '')::date;
  v_recurring boolean := coalesce((p_data ->> 'is_recurring')::boolean, false);
  v_recurrence text := case when v_recurring then p_data ->> 'recurrence' end;
  v_next date := case when v_recurring then nullif(p_data ->> 'next_due_on', '')::date end;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if v_id is not null then
    select * into v from public.expenses where id = v_id for update;
    if not found then
      raise exception 'Expense not found' using errcode = 'P0002';
    end if;
    if v.status <> 'active' then
      raise exception '% is voided and can''t be changed.', v.number using errcode = 'P0001';
    end if;
  end if;
  perform public._check_expense(p_data, v);

  if v_recurring then
    if v_recurrence is null or v_recurrence not in ('monthly', 'yearly') then
      raise exception 'Choose how often it repeats.' using errcode = 'P0001';
    end if;
    if v.recurring_source_id is not null then
      raise exception 'This expense was posted from a repeating one. Change the repeat on the original instead.' using errcode = 'P0001';
    end if;
    v_next := coalesce(v_next, public._next_due(v_spent, v_spent, v_recurrence));
    if v_next <= v_spent then
      raise exception 'The next due date must be after the date spent.' using errcode = 'P0001';
    end if;
  end if;

  if v_id is null then
    insert into public.expenses (number, category_id, amount_paise, spent_on, paid_via)
    values ('EXP-' || nextval('public.expense_number_seq'), (p_data ->> 'category_id')::uuid, (p_data ->> 'amount_paise')::int, v_spent, p_data ->> 'paid_via')
    returning id into v_id;
  end if;

  update public.expenses set
    category_id = (p_data ->> 'category_id')::uuid,
    amount_paise = (p_data ->> 'amount_paise')::int,
    tax_paise = coalesce(nullif(p_data ->> 'tax_paise', '')::int, 0),
    spent_on = v_spent,
    paid_via = p_data ->> 'paid_via',
    vendor_id = nullif(p_data ->> 'vendor_id', '')::uuid,
    description = nullif(btrim(p_data ->> 'description'), ''),
    attachments = coalesce(p_data -> 'attachments', '[]'::jsonb),
    is_recurring = v_recurring,
    recurrence = v_recurrence,
    next_due_on = v_next
  where id = v_id;
  return v_id;
end;
$$;

create function public.books_void_expense(p_id uuid, p_reason text)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'Please give a short reason for voiding.' using errcode = 'P0001';
  end if;
  -- Voiding a repeating expense also stops its reminders.
  update public.expenses
     set status = 'voided', void_reason = left(btrim(p_reason), 300), voided_at = now(),
         is_recurring = false, recurrence = null, next_due_on = null
   where id = p_id and status = 'active';
  if not found then
    raise exception 'Only an active expense can be voided.' using errcode = 'P0001';
  end if;
end;
$$;

-- Confirm one due occurrence of a repeating expense: posts a new expense (fields as in books_save_expense; amount
-- and date can differ from the template) and moves the reminder to the next date. p_due_on must be the template's
-- current due date, so a double tap can't post it twice.
create function public.books_confirm_recurring(p_source_id uuid, p_due_on date, p_data jsonb)
returns uuid
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.expenses;
  v_id uuid;
  v_first date;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  select * into v from public.expenses where id = p_source_id for update;
  if not found or not v.is_recurring or v.status <> 'active' then
    raise exception 'This expense doesn''t repeat any more.' using errcode = 'P0001';
  end if;
  if p_due_on is distinct from v.next_due_on then
    raise exception 'That date has already been confirmed or skipped. Reload the page.' using errcode = 'P0001';
  end if;
  if p_due_on > (now() at time zone 'Asia/Kolkata')::date + 7 then
    raise exception 'It isn''t due yet.' using errcode = 'P0001';
  end if;
  perform public._check_expense(p_data, v);

  insert into public.expenses (number, category_id, amount_paise, tax_paise, spent_on, paid_via, vendor_id, description, attachments, recurring_source_id)
  values ('EXP-' || nextval('public.expense_number_seq'), (p_data ->> 'category_id')::uuid, (p_data ->> 'amount_paise')::int,
          coalesce(nullif(p_data ->> 'tax_paise', '')::int, 0), (p_data ->> 'spent_on')::date, p_data ->> 'paid_via',
          nullif(p_data ->> 'vendor_id', '')::uuid, nullif(btrim(p_data ->> 'description'), ''), coalesce(p_data -> 'attachments', '[]'::jsonb), v.id)
  returning id into v_id;

  -- The series is counted from the template's own date.
  v_first := v.spent_on;
  update public.expenses set next_due_on = public._next_due(v_first, p_due_on, v.recurrence) where id = v.id;
  return v_id;
end;
$$;

create function public.books_skip_recurring(p_source_id uuid, p_due_on date)
returns date
language plpgsql
security definer set search_path = ''
as $$
declare
  v public.expenses;
  v_next date;
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  select * into v from public.expenses where id = p_source_id for update;
  if not found or not v.is_recurring or v.status <> 'active' then
    raise exception 'This expense doesn''t repeat any more.' using errcode = 'P0001';
  end if;
  if p_due_on is distinct from v.next_due_on then
    raise exception 'That date has already been confirmed or skipped. Reload the page.' using errcode = 'P0001';
  end if;
  v_next := public._next_due(v.spent_on, p_due_on, v.recurrence);
  update public.expenses set next_due_on = v_next where id = v.id;
  return v_next;
end;
$$;

create function public.books_stop_recurring(p_id uuid)
returns void
language plpgsql
security definer set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorised' using errcode = '42501';
  end if;
  update public.expenses set is_recurring = false, recurrence = null, next_due_on = null where id = p_id and is_recurring;
  if not found then
    raise exception 'This expense doesn''t repeat.' using errcode = 'P0001';
  end if;
end;
$$;

revoke execute on function public.books_save_expense(uuid, jsonb) from public, anon;
grant execute on function public.books_save_expense(uuid, jsonb) to authenticated;                  -- is_admin() inside
revoke execute on function public.books_void_expense(uuid, text) from public, anon;
grant execute on function public.books_void_expense(uuid, text) to authenticated;
revoke execute on function public.books_confirm_recurring(uuid, date, jsonb) from public, anon;
grant execute on function public.books_confirm_recurring(uuid, date, jsonb) to authenticated;
revoke execute on function public.books_skip_recurring(uuid, date) from public, anon;
grant execute on function public.books_skip_recurring(uuid, date) to authenticated;
revoke execute on function public.books_stop_recurring(uuid) from public, anon;
grant execute on function public.books_stop_recurring(uuid) to authenticated;

-- ===========================================================================
-- Mark this database as production (checked by npm run check:launch; the demo seed refuses to run here)
